#!/usr/bin/env python3

import unittest

from koehnlab.molecular import pointGroupGenerators

import numpy as np


def _groupSize(name: str) -> int:
    """Number of different matrices generated by the generators of the group"""

    def key(matrix):
        return tuple((np.round(matrix, 6) + 0.0).ravel().tolist())

    elements = {key(np.eye(3)): np.eye(3)}
    queue = [np.eye(3)]
    generators = [matrix for _, matrix in pointGroupGenerators(name)]
    while queue:
        current = queue.pop()
        for generator in generators:
            product = generator @ current
            if key(product) not in elements:
                elements[key(product)] = product
                queue.append(product)
                assert len(elements) < 1000

    return len(elements)


class TestPointGroups(unittest.TestCase):

    def test_group_orders(self):
        orders = {
            "C1": 1, "Cs": 2, "Ci": 2, "C2": 2, "C3": 3, "C6": 6,
            "C2v": 4, "C3v": 6, "C6v": 12, "C2h": 4, "C3h": 6, "C4h": 8,
            "D2": 4, "D3": 6, "D2h": 8, "D3h": 12, "D6h": 24, "D2d": 8, "D3d": 12, "D4d": 16,
            "S4": 4, "S6": 6, "S8": 8,
            "T": 12, "Td": 24, "Th": 24, "O": 24, "Oh": 48, "I": 60, "Ih": 120,
        }  # fmt: skip

        for name, order in orders.items():
            with self.subTest(name):
                self.assertEqual(_groupSize(name), order)

    def test_orthogonal_matrices(self):
        for name in ("D3d", "Oh", "Ih", "S6"):
            for _, matrix in pointGroupGenerators(name):
                np.testing.assert_allclose(matrix @ matrix.T, np.eye(3), atol=1e-12)

    def test_unknown_groups(self):
        for name in ("", "X", "C0v", "D1", "S3", "S5", "Cv", "C2x", "Td2", "c2v"):
            with self.subTest(name):
                with self.assertRaises(ValueError):
                    pointGroupGenerators(name)


if __name__ == "__main__":
    unittest.main()
